public class InlineFunctions {
    public void process(Node externs, Node root) {
        if (externals == null || root == null) {
            throw new IllegalArgumentException("Externs and root cannot be null.");
        }

        // Find called functions
        Set<String> changed = Sets.newHashSet();
        findCalledFunctions(externals, changed);

        // Process the AST
        processExternalNodes(externals);
        processRootNode(root);
    }

    private void processExternalNodes(Node externs) {
        if (externals == null) {
            throw new IllegalStateException("Externs cannot be null.");
        }

        for (Node node : externs.getNodes()) {
            findCalledFunctions(node, changed);
        }
    }

    private void processRootNode(Node root) {
        if (root == null) {
            throw new IllegalStateException("Root cannot be null.");
        }

        processChildNodes(root);
    }

    private void processChildNodes(Node node) {
        if (node == null) {
            return;
        }

        for (Node child : node.getChildren()) {
            processChildNodes(child);
        }
    }

    // Other methods
}
