    @Rule
    public ExpectedException thrown = new ExpectedException();

    private ObjectInputStream objInputStream;

    @Before
    public void setUp() throws IOException {
        this.objInputStream = Mockito.spy(ObjectInputStream.class);
        Mockito.doNothing().when(objInputStream, "resolveClass");
    }

    @After
    public void tearDown() {
        this.objInputStream = null;
    }

    @Test
    public void testResolveClass_PrimitiveType_ReturnsCorrectPrimitiveType() throws IOException, ClassNotFoundException {
        String name = "byte";
        Class<?> expected = byte.class;
        Mockito.doReturn(expected).when(objInputStream).resolveClass(Mockito.any(ObjectStreamClass.class));

        Object result = this.objInputStream.resolveClass(new ObjectStreamClass(name));
        Assert.assertEquals(expected, result.getClass());
    }

    @Test
    public void testResolveClass_NotPrimitiveType_ReturnsCorrectClass() throws IOException {
        String name = "java/lang/Integer";
        Class<?> expected = int.class;

        Mockito.doNothing().when(objInputStream).resolveClass(Mockito.any(ObjectStreamClass.class));
        Mockito.doReturn(Class.forName(name, false, classLoader)).when(objInputStream).resolveClass(Mockito.<ObjectStreamClass>any());

        Object result = this.objInputStream.resolveClass(new ObjectStreamClass(name));
        Assert.assertThat(result.getClass(), is(instanceOf(Integer.class)));
    }

    @Test
    public void testResolveClass_NotPrimitiveOrBuiltIn_ReturnsCorrectClass() throws IOException {
        String name = "custom/package/CustomClass";

        Mockito.doNothing().when(objInputStream).resolveClass(Mockito.<ObjectStreamClass>any());
        Mockito.doReturn(Class.forName(name, false, classLoader)).when(objInputStream).resolveClass(Mockito.<ObjectStreamClass>any());

        Object result = this.objInputStream.resolveClass(new ObjectStreamClass(name));
        Assert.assertThat(result.getClass(), is(instanceOf(Object.class)));
    }

    @Test
    public void testResolveClass_ClassNotFound_ThowsClassNotFoundException() throws IOException {
        String name = "nonexistent/package/NonExistentClass";

        Mockito.doNothing().when(objInputStream).resolveClass(Mockito.<ObjectStreamClass>any());
        Mockito.doThrow(new ClassNotFoundException()).when(objInputStream).resolveClass(Mockito.any(ObjectStreamClass.class));

        thrown.expect(IOException.class);
        thrown.expectMessage("Could not find class: " + name);
        this.objInputStream.resolveClass(new ObjectStreamClass(name));
    }
